CREATE TABLE "searcher_engines" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "site name" TEXT COLLATE NOCASE NOT NULL, "identifier" TEXT COLLATE NOCASE NOT NULL, "hidden" INTEGER NOT NULL DEFAULT '0', "old-identifier" TEXT COLLATE NOCASE NOT NULL, "url-prefix" TEXT COLLATE NOCASE NOT NULL, "url-suffix" TEXT COLLATE NOCASE NOT NULL, "baseurl" TEXT COLLATE NOCASE, "nsfw" INTEGER NOT NULL DEFAULT '0');

CREATE TABLE "searcher_searches" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "searchTerm" TEXT COLLATE NOCASE NOT NULL, "engine" TEXT COLLATE NOCASE NOT NULL, "datetime" TEXT COLLATE NOCASE NOT NULL, "searcher" INTEGER NOT NULL);

CREATE UNIQUE INDEX "searcher_engines_identifier" ON "searcher_engines" ("identifier");
